package com.bank.atm;

import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Returns the K nearest ATM coordinates to the origin (customer location).
public class AtmLocator {

    private static final Logger log = Logger.getLogger(AtmLocator.class.getName());

    public int[][] kClosest(int[][] points, int k) {
        // max-heap by squared distance (farthest on top)
        PriorityQueue<int[]> heap = new PriorityQueue<>(
                (a, b) -> Long.compare(sq(b), sq(a)));
        for (int[] p : points) {
            heap.offer(p);
            if (heap.size() > k) {
                heap.poll(); // evict the farthest
            }
        }
        int[][] result = new int[heap.size()][];
        int i = 0;
        while (!heap.isEmpty()) {
            result[i++] = heap.poll();
        }
        log.info("K closest ATMs: " + Arrays.deepToString(result));
        return result;
    }

    private long sq(int[] p) {
        return (long) p[0] * p[0] + (long) p[1] * p[1]; // squared distance
    }
}
