package com.bank.atm;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class AtmLocatorDemo {

    private static final Logger log = Logger.getLogger(AtmLocatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — K Nearest ATMs");
        // ATM coordinates relative to customer at origin (0,0)
        int[][] atms = {{1, 3}, {-2, 2}, {5, 8}, {0, 1}, {3, 3}};
        int k = 2;

        AtmLocator locator = new AtmLocator();
        locator.kClosest(atms, k);
    }
}
